'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = v => '฿' + Number(v || 0).toLocaleString('th-TH', {maximumFractionDigits:2});
const fmt = v => new Date(v).toLocaleString('th-TH', {timeZone:'Asia/Bangkok',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const today = () => new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const localDay = v => new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const uuid = () => crypto.randomUUID ? crypto.randomUUID() : Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const icons = {
 cup:'<path d="M4 8h12v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM16 9h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2M3 23h15"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 bag:'<path d="M5 7h14l1 14H4zM9 8V6a3 3 0 0 1 6 0v2"/>',
 receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2zM9 8h6M9 12h6M9 16h3"/>',
 table:'<path d="M3 7h18v4H3zM5 11v10m14-10v10M7 3h10"/>',
 box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 4 9-4M12 11v11M7 5l9 4"/>',
 chart:'<path d="M4 3v18h17M9 17v-5m5 5V7m5 10V4"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
 check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
 logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
 qr:'<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h3v3h3v3h-6zM21 12v3M12 3v3M12 9v3H9M3 12h3M12 18v3"/>',
 edit:'<path d="m15 5 4 4M4 20l4-1L20 7a3 3 0 0 0-4-4L4 15z"/>',
 leaf:'<path d="M20 3C6 2 2 9 6 16c7 4 14 0 14-13zM4 20 16 8"/>',
 bakery:'<path d="m3 13 3-5 4-2h4l4 2 3 5-3 6H6zM8 8l-2 9m10-9 2 9M12 6v14"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
 print:'<path d="M6 8V3h12v5M6 16H3V9h18v7h-3M6 13h12v8H6zM17 11h1"/>',
 refresh:'<path d="M20 7V3l-3 3A8 8 0 1 0 3 13M20 3h-5M21 11a8 8 0 0 1-3 7"/>',
 wallet:'<path d="M20 7H5a3 3 0 0 1 0-6h13v6M3 4v15a2 2 0 0 0 2 2h15V7M20 11h-5v5h5"/>',
 shield:'<path d="m12 3 8 3v7c0 5-8 9-8 9S4 18 4 13V6zM8 12l3 3 5-6"/>',
 store:'<path d="M3 9l2-6h14l2 6M3 9v3a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0V9M5 15v6h14v-6M10 21v-6h4v6"/>'
};
const ico = (n, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[n] || icons.cup}</svg>`;
const labels = {new:'รอรับออเดอร์',preparing:'กำลังเตรียม',ready:'พร้อมเสิร์ฟ',served:'เสิร์ฟแล้ว',cancelled:'ยกเลิก'};
const roles = {manager:'ผู้จัดการ',cashier:'แคชเชียร์',barista:'บาริสต้า'};
const categories = {all:'ทั้งหมด',coffee:'กาแฟ',tea:'ชาและมัทฉะ',chocolate:'ช็อกโกแลต',bakery:'ขนมอบ'};
const statusPill = s => `<span class="pill ${s==='new'?'gold':s==='ready'?'green':s==='cancelled'?'red':s==='preparing'?'blue':''}">${esc(labels[s] || s)}</span>`;
const state = {admin:location.pathname.startsWith('/admin'),view:new URLSearchParams(location.search).get('view') || (location.pathname.startsWith('/admin')?'overview':'menu'),csrf:'',user:null,menu:null,data:null,cart:[],orders:[],token:decodeURIComponent(location.pathname.split('/table/')[1] || ''),category:'all',search:'',orderFilter:'live',orderSearch:'',custom:null,busy:false,requestId:uuid(),report:null,reportFrom:today(),reportTo:today(),connected:true};
let toastTimer, pollTimer, lastFocus;
function toast(message, error=false){const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.className='';},4200);}
async function api(path, body){const headers={'Accept':'application/json'};if(body!==undefined){headers['Content-Type']='application/json';if(state.csrf)headers['X-CSRF-Token']=state.csrf;}const res=await fetch(path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});const type=res.headers.get('content-type') || '';if(!type.includes('json'))throw Error('ไม่สามารถเชื่อมต่อร้านได้ กรุณาลองอีกครั้ง');const data=await res.json();if(!res.ok || data.ok===false){if(res.status===401 && state.admin && !path.includes('/login')){state.user=null;renderLogin();}throw Error(data.error || 'เกิดข้อผิดพลาด กรุณาลองอีกครั้ง');}return data;}
function storageKey(type){return 'lamoon_'+type+'_'+state.token;}
function saveCart(){try{localStorage.setItem(storageKey('cart'),JSON.stringify({items:state.cart,requestId:state.requestId,note:state.cartNote||''}));}catch{}}
function changedCart(){state.requestId=uuid();saveCart();}
function readCart(){try{const c=JSON.parse(localStorage.getItem(storageKey('cart')) || '{}');state.cart=(c.items||[]).filter(x=>state.menu.products.some(p=>p.id===x.product_id));state.requestId=c.requestId || uuid();state.cartNote=c.note||'';syncCartPrices();}catch{state.cart=[];}}
function storedOrders(){try{return JSON.parse(localStorage.getItem(storageKey('orders')) || '[]');}catch{return [];}}
function brand(){return `<span class="brand-emblem">${ico('cup')}</span><span class="wordmark">${esc(state.menu?.shop?.name || state.data?.shop?.name || 'ละมุน')}<span>LAMOON COFFEE</span></span>`;}
function showModal(title, body, footer='',wide=false,extra=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''} ${extra}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="ปิด">${ico('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal .icon-btn')?.focus());}
function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow='';state.custom=null;lastFocus?.focus?.();}
function photoFor(p){return ['latte','matcha','croissant'].includes(p.image) ? `/static/${p.image}.png`:null;}
function productIcon(p){return p.category==='bakery'?'bakery':p.category==='tea'?'leaf':'cup';}
function calcPrice(p,o){return Number(p.price)+(p.drink?(o.size==='large'?15:0)+(o.milk==='oat'?20:0)+(o.shot?15:0):0);}
function optionText(p,o){if(!p?.drink)return 'อบสด พร้อมเสิร์ฟ';return [o.temperature==='hot'?'ร้อน':'เย็น',o.size==='large'?'แก้วใหญ่':'แก้วปกติ','หวาน '+(o.sweetness||'0')+'%',o.milk==='oat'?'นมโอ๊ต':'',o.shot?'เพิ่มช็อต':''].filter(Boolean).join(' · ');}
function itemOptions(item){if(item.options_label)return item.options_label;const current=(state.menu?.products||state.data?.products||[]).find(x=>x.id===item.product_id);const p={...current,drink:item.category?item.category!=='bakery':current?.drink};return optionText(p,item.options||{});}
function syncCartPrices(){let changed=false;for(const x of state.cart){const p=state.menu.products.find(p=>p.id===x.product_id);if(p){const price=calcPrice(p,x.options);if(price!==x.price){x.price=price;changed=true;}}}if(changed)saveCart();return changed;}

function cartTotal(){return state.cart.reduce((a,x)=>a+x.price*x.qty,0);}
function cartCount(){return state.cart.reduce((a,x)=>a+x.qty,0);}
function customerHeader(){const demo=state.menu.shop.demo;return `${demo?'<div class="demo-strip">ร้านตัวอย่าง · ออเดอร์และยอดขายเริ่มต้นเป็นข้อมูลทดลอง</div>':''}<header class="shop-header"><a class="brand" href="${state.token?'/table/'+encodeURIComponent(state.token):'/'}" aria-label="หน้าเมนูละมุน">${brand()}</a><nav class="shop-nav" aria-label="เมนูหลัก"><button class="nav-link ${state.view==='menu'?'active':''}" data-action="customer-view" data-view="menu">เมนู</button><button class="nav-link ${state.view==='history'?'active':''}" data-action="customer-view" data-view="history">ออเดอร์ของฉัน</button><a href="/admin" class="staff-link">${ico('shield')} สำหรับพนักงาน</a></nav></header>`;}
function cartHtml(modal=false){const table=state.menu.table;return `<aside class="cart-panel"><div class="table-banner"><div><small>ออเดอร์สำหรับ</small><strong>${table?'โต๊ะ '+esc(table.name):'ยังไม่ได้เลือกโต๊ะ'}</strong></div>${ico('table')}</div><div class="cart-inner"><div class="cart-title"><h2>รายการที่เลือก</h2><span>${cartCount()} รายการ</span></div>${state.cart.length?state.cart.map((x,i)=>`<div class="cart-item"><div class="row between"><h3>${esc(x.name)}</h3><span class="num small">${money(x.price*x.qty)}</span></div><div class="options">${esc(optionText(state.menu.products.find(p=>p.id===x.product_id),x.options))}${x.note?'<br>'+esc(x.note):''}</div><div class="row between"><div class="qty"><button data-action="cart-qty" data-index="${i}" data-delta="-1" aria-label="ลดจำนวน ${esc(x.name)}">${ico('minus')}</button><span>${x.qty}</span><button data-action="cart-qty" data-index="${i}" data-delta="1" aria-label="เพิ่มจำนวน ${esc(x.name)}">${ico('plus')}</button></div><button class="btn ghost sm" data-action="cart-remove" data-index="${i}">นำออก</button></div></div>`).join(''):`<div class="cart-empty">${ico('bag')}<p>เลือกอะไรอร่อย ๆ กัน</p><small>แตะเมนูเพื่อเพิ่มลงในรายการ</small></div>`}<div class="cart-summary"><div class="row between"><span>รวมค่าอาหารและเครื่องดื่ม</span><span class="num">${money(cartTotal())}</span></div><div class="row between total"><span>ยอดรวม</span><strong class="num">${money(cartTotal())}</strong></div></div><textarea class="cart-note" id="${modal?'cart-note-modal':'cart-note'}" maxlength="250" placeholder="หมายเหตุสำหรับร้าน (ถ้ามี)" aria-label="หมายเหตุออเดอร์">${esc(state.cartNote||'')}</textarea><button class="btn w-full" data-action="submit-order" ${!state.cart.length||!table||!state.menu.shop.open||state.busy?'disabled':''}>${state.busy?'กำลังส่งออเดอร์…':state.menu.shop.open?'ยืนยันออเดอร์':'ร้านปิดรับออเดอร์'}</button><p class="tiny muted mt16" style="text-align:center">ชำระเงินที่เคาน์เตอร์เมื่อทานเสร็จ</p></div><div class="service-links"><button data-action="service" data-type="help" ${!table?'disabled':''}>${ico('bell')} เรียกพนักงาน</button><button data-action="service" data-type="bill" ${!table?'disabled':''}>${ico('receipt')} ขอเช็กบิล</button></div></aside>`;}
function menuCardsHtml(){let products=state.menu.products.filter(p=>(state.category==='all'||p.category===state.category)&&(!state.search||(p.name+' '+p.en+' '+p.description).toLowerCase().includes(state.search.toLowerCase())));if(!products.length)return `<div class="empty">${ico('search','large')}<h3>ยังไม่พบเมนูนี้</h3><p class="small">ลองค้นหาคำอื่น หรือเลือกหมวดทั้งหมด</p></div>`;const featured=products.filter(p=>photoFor(p));const regular=products.filter(p=>!photoFor(p));return `${featured.length?`<div class="section-label"><h2>เมนูแนะนำ</h2><span>ชงสด อบใหม่</span></div><div class="featured-grid">${featured.map(p=>`<article class="product-card ${!p.available?'sold-out':''}" tabindex="0" role="button" data-action="customize" data-id="${esc(p.id)}" aria-label="เลือก ${esc(p.name)}${!p.available?' หมดชั่วคราว':''}"><div class="product-photo"><img src="${photoFor(p)}" alt="${esc(p.name)}" loading="eager"><span class="photo-label">${p.available?'HOUSE FAVORITE':'หมดชั่วคราว'}</span></div><div class="product-copy"><h3>${esc(p.name)}</h3><div class="product-en">${esc(p.en)}</div><p class="product-description">${esc(p.description)}</p><div class="product-price"><span class="num">${money(p.price)}</span><span class="add-circle">${ico('plus')}</span></div></div></article>`).join('')}</div>`:''}${regular.length?`<div class="section-label"><h2>${featured.length?'อร่อยได้อีก':'เมนูของเรา'}</h2><span>${regular.length} เมนู</span></div><div class="regular-grid">${regular.map(p=>`<article class="product-row ${!p.available?'sold-out':''}" tabindex="0" role="button" data-action="customize" data-id="${esc(p.id)}" aria-label="เลือก ${esc(p.name)}"><div class="product-symbol">${ico(productIcon(p))}</div><div class="details"><h3>${esc(p.name)}</h3><div class="product-en">${esc(p.en)}</div>${!p.available?'<span class="tiny muted">หมดชั่วคราว</span>':''}</div><span class="num price">${money(p.price)}</span><span class="add-circle">${ico('plus')}</span></article>`).join('')}</div>`:''}`;}
function menuHtml(){const m=state.menu;return `<div class="menu-heading"><div><span class="eyebrow">A LITTLE PAUSE, A GOOD CUP.</span><h1>วันนี้ จิบอะไรดี</h1><p>${esc(m.shop.subtitle || 'กาแฟหอม ๆ กับขนมชิ้นโปรดของคุณ')}</p></div><div class="open-note"><span ${!m.shop.open?'style="color:var(--muted)"':''}><i class="status-dot"></i>${m.shop.open?'เปิดรับออเดอร์':'ปิดรับออเดอร์'}</span><small>${esc(m.shop.opening_hours || '08:00 – 18:00')}</small></div></div>${!m.table?`<div class="info-box">สแกน QR ที่โต๊ะ เพื่อให้เรานำเมนูไปเสิร์ฟได้ถูกโต๊ะ</div>`:''}${m.shop.demo&&m.demo_tables?.length?`<div class="row between mb16"><span class="pill">${ico('table')} โต๊ะ ${esc(m.table?.name || '')}</span><label class="small muted row">ทดลองโต๊ะ <select id="demo-table" aria-label="เลือกโต๊ะทดลอง" style="padding:5px 9px;font-size:.8125rem">${m.demo_tables.map(t=>`<option value="${esc(t.token)}" ${t.token===state.token?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div>`:m.table?`<div class="mb16"><span class="pill">${ico('table')} โต๊ะ ${esc(m.table.name)}</span></div>`:''}<div class="menu-tools"><div class="searchbox">${ico('search')}<input id="menu-search" type="search" value="${esc(state.search)}" placeholder="ค้นหาเมนูที่อยากทาน" aria-label="ค้นหาเมนู"></div><div class="categories" role="group" aria-label="หมวดเมนู">${Object.entries(categories).map(([key,name])=>`<button class="chip ${state.category===key?'active':''}" data-action="category" data-category="${key}" aria-pressed="${state.category===key}">${name}</button>`).join('')}</div></div><div id="menu-cards">${menuCardsHtml()}</div><footer class="menu-footer"><span>ทุกแก้วชงใหม่ เมื่อคุณสั่ง</span><span>แพ้อาหารหรือมีข้อจำกัด แจ้งพนักงานก่อนสั่ง</span></footer>`;}
function historyHtml(){return `<div class="customer-orders-title"><span class="eyebrow">YOUR LITTLE MOMENT</span><h1>ออเดอร์ของฉัน</h1><p class="small muted mt16">โต๊ะ ${esc(state.menu.table?.name || '—')} · สถานะจะอัปเดตอัตโนมัติ</p></div>${state.orders.length?`<div class="order-history">${state.orders.map(o=>`<article class="history-card"><div class="order-head"><div><div class="order-number">#${esc(o.number)}</div><div class="tiny muted">${fmt(o.created_at)}</div></div><div class="stack" style="align-items:flex-end;gap:6px">${statusPill(o.status)}${o.paid?'<span class="pill green">ชำระแล้ว</span>':''}</div></div>${o.status!=='cancelled'?`<div class="progress">${['new','preparing','ready','served'].map((s,i)=>`<span class="${i<=['new','preparing','ready','served'].indexOf(o.status)?'done':''}"></span>`).join('')}</div><div class="step-label"><span>รับออเดอร์</span><span>เตรียม</span><span>พร้อมเสิร์ฟ</span><span>เสิร์ฟแล้ว</span></div>`:'<p class="small muted">ร้านยกเลิกรายการนี้แล้ว</p>'}<div class="line"></div>${o.items.map(x=>`<div class="history-item"><div>${x.qty} × ${esc(x.name)}<div class="tiny muted">${esc(itemOptions(x))}${x.note?' · '+esc(x.note):''}</div></div><span class="num">${money((x.price ?? x.unit_price)*x.qty)}</span></div>`).join('')}<div class="row between mt16"><strong class="small">ยอดรวม</strong><strong class="num" style="font-size:1.5rem;font-weight:normal">${money(o.total)}</strong></div></article>`).join('')}</div>`:`<div class="empty">${ico('receipt','large')}<h3>ยังไม่มีออเดอร์</h3><p class="small">เลือกเมนูที่ชอบ แล้วเราจะเตรียมให้คุณ</p><button class="btn secondary mt24" data-action="customer-view" data-view="menu">เลือกเมนู</button></div>`}`;}
function renderCustomer(){if(!state.menu)return;$('#app').innerHTML=`${customerHeader()}${!state.connected?'<div class="connection-banner">การเชื่อมต่อขัดข้อง กำลังลองเชื่อมต่อใหม่</div>':''}<div class="shop-body"><main class="shop-content">${state.view==='history'?historyHtml():menuHtml()}</main>${cartHtml()}</div><div class="mobile-cart-bar"><button class="btn" data-action="show-cart"><span><span class="cart-badge">${cartCount()}</span>${state.cart.length?'ดูรายการที่เลือก':'รายการที่เลือก'}</span><span class="num">${money(cartTotal())}</span></button></div>`;}
function renderCustomize(){const c=state.custom,p=state.menu.products.find(x=>x.id===c.id);const opts=c.options;showModal(esc(p.name),`<p class="product-en">${esc(p.en)}</p><p class="custom-description mt16">${esc(p.description)}</p>${p.drink?`<div class="option-block"><div class="option-title">ร้อน / เย็น</div><div class="option-grid">${[['iced','เย็น'],['hot','ร้อน']].map(([v,l])=>`<button class="option-btn ${opts.temperature===v?'selected':''}" data-action="option" data-field="temperature" data-value="${v}" aria-pressed="${opts.temperature===v}">${l}</button>`).join('')}</div></div><div class="option-block"><div class="option-title">ขนาดแก้ว</div><div class="option-grid">${[['regular','ปกติ'],['large','ใหญ่ +฿15']].map(([v,l])=>`<button class="option-btn ${opts.size===v?'selected':''}" data-action="option" data-field="size" data-value="${v}" aria-pressed="${opts.size===v}">${l}</button>`).join('')}</div></div><div class="option-block"><div class="option-title">ความหวาน</div><div class="option-grid">${['0','25','50','100'].map(v=>`<button class="option-btn ${opts.sweetness===v?'selected':''}" data-action="option" data-field="sweetness" data-value="${v}" aria-pressed="${opts.sweetness===v}">${v==='0'?'ไม่หวาน':v+'%'}</button>`).join('')}</div></div>${p.recipe?.milk?`<div class="option-block"><div class="option-title">เลือกนม</div><div class="option-grid">${[['regular','นมปกติ'],['oat','นมโอ๊ต +฿20']].map(([v,l])=>`<button class="option-btn ${opts.milk===v?'selected':''}" data-action="option" data-field="milk" data-value="${v}" aria-pressed="${opts.milk===v}">${l}</button>`).join('')}</div></div>`:''}${p.category==='coffee'?`<label class="check mb24"><input type="checkbox" id="extra-shot" ${opts.shot?'checked':''}>เพิ่มเอสเปรสโซ 1 ช็อต +฿15</label>`:''}`:''}<div class="field mb24"><label for="item-note">หมายเหตุ (ถ้ามี)</label><textarea id="item-note" maxlength="200" placeholder="เช่น แยกน้ำแข็ง">${esc(c.note)}</textarea></div><div class="row between"><span class="small">จำนวน</span><div class="qty"><button data-action="custom-qty" data-delta="-1" aria-label="ลดจำนวน">${ico('minus')}</button><span>${c.qty}</span><button data-action="custom-qty" data-delta="1" aria-label="เพิ่มจำนวน">${ico('plus')}</button></div></div>`,`<button class="btn w-full" data-action="add-cart">เพิ่มลงรายการ · <span id="custom-total">${money(calcPrice(p,opts)*c.qty)}</span></button>`);}
function captureCustom(){if(!state.custom)return;state.custom.note=$('#item-note')?.value||'';state.custom.options.shot=$('#extra-shot')?.checked||false;}
async function loadOrders(){const saved=storedOrders();const result=await Promise.allSettled(saved.map(x=>api(`/api/order?id=${encodeURIComponent(x.id)}&key=${encodeURIComponent(x.key)}`)));state.orders=result.filter(x=>x.status==='fulfilled').map(x=>x.value.order).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));}
async function loadCustomer(){const result=await api('/api/menu'+(state.token?'?token='+encodeURIComponent(state.token):''));state.menu=result;if(!state.token&&result.table&&result.demo_tables)state.token=result.demo_tables.find(t=>String(t.name)===String(result.table.name))?.token||'';readCart();await loadOrders();renderCustomer();}
const adminPages=[['overview','grid','ภาพรวม'],['orders','receipt','ออเดอร์'],['tables','table','โต๊ะและบิล'],['menu','cup','จัดการเมนู'],['stock','box','สต็อก'],['reports','chart','รายงาน'],['staff','users','พนักงาน'],['settings','settings','ตั้งค่าร้าน']];
function canManager(){return state.user?.role==='manager';}
function canCashier(){return ['manager','cashier'].includes(state.user?.role);}
function visiblePages(){return adminPages.filter(([p])=>canManager()||(!['staff','settings','menu','stock','reports'].includes(p))||(state.user?.role==='cashier'&&p==='reports'));}
function heading(title, subtitle='',right=''){return `<div class="page-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;}
function metricsHtml(values){return `<div class="metrics">${values.map(([label,value,sub,icon])=>`<div class="metric"><div class="metric-label"><span>${label}</span>${ico(icon)}</div><div class="metric-value">${value}</div><div class="metric-foot">${sub}</div></div>`).join('')}</div>`;}
function ordersForTable(id){return state.data.orders.filter(o=>String(o.table_id)===String(id)&&!o.paid&&o.status!=='cancelled');}
function payToday(){return state.data.payments.filter(x=>localDay(x.created_at)===today());}
function todayOrders(){return state.data.orders.filter(x=>localDay(x.created_at)===today()&&x.status!=='cancelled');}
function chartHtml(daily){const max=Math.max(1,...daily.map(x=>x.total));return `<div class="chart">${daily.map(x=>`<div class="chart-col"><span class="chart-amount">${Number(x.total||0).toLocaleString('th-TH')}</span><div class="chart-bar" style="height:${Math.max(2,x.total/max*155)}px" title="${esc(x.date)} ${money(x.total)}"></div><span class="tiny">${new Date(x.date+'T00:00:00+07:00').toLocaleDateString('th-TH',{day:'numeric',month:'short'})}</span></div>`).join('')}</div>`;}
function sevenDays(){return Array.from({length:7},(_,i)=>{const d=new Date(Date.now()-(6-i)*86400000),day=localDay(d);return {date:day,total:state.data.payments.filter(x=>localDay(x.created_at)===day).reduce((a,x)=>a+x.amount,0)};});}
function bestSellers(orders){const map={};orders.filter(o=>o.status!=='cancelled').forEach(o=>o.items.forEach(x=>{const m=map[x.name]||{name:x.name,qty:0,total:0};m.qty+=x.qty;m.total+=(x.price??x.unit_price)*x.qty;map[x.name]=m;}));return Object.values(map).sort((a,b)=>b.qty-a.qty);}
function bestHtml(items){return items.length?items.slice(0,5).map((x,i)=>`<div class="best-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x.name)}</h3><span class="tiny muted">ยอดรายการ ${money(x.total)}</span></div><strong>${x.qty} <span class="tiny muted">ชิ้น/แก้ว</span></strong></div>`).join(''):'<div class="empty small">ยังไม่มีรายการขาย</div>';}
function orderRows(orders,actions=false){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>ออเดอร์</th><th>โต๊ะ</th><th>เวลา</th><th>ยอดรวม</th><th>สถานะ</th>${actions?'<th></th>':''}</tr></thead><tbody>${orders.map(o=>`<tr><td class="num">#${esc(o.number)}</td><td>${esc(o.table_name)}</td><td class="tiny muted">${fmt(o.created_at)}</td><td class="num">${money(o.total)}</td><td>${o.paid?'<span class="pill green">ชำระแล้ว</span>':statusPill(o.status)}</td>${actions?`<td><button class="btn secondary sm" data-action="order-detail" data-id="${esc(o.id)}">ดูรายการ</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${actions?6:5}" class="empty">ยังไม่มีออเดอร์</td></tr>`}</tbody></table></div>`;}
function overviewHtml(){const paid=payToday(),orders=todayOrders(),revenue=paid.reduce((a,x)=>a+x.amount,0),active=state.data.orders.filter(o=>['new','preparing','ready'].includes(o.status)),occupied=state.data.tables.filter(t=>ordersForTable(t.id).length),low=state.data.stock.filter(x=>x.qty<=x.low),alerts=state.data.alerts.filter(x=>!x.resolved);return `${heading('ภาพรวมวันนี้','ทุกอย่างพร้อม สำหรับวันดี ๆ อีกวัน',`<span class="date-pill">${new Date().toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',weekday:'short',day:'numeric',month:'long',year:'numeric'})}</span>`)}${alerts.length?`<div class="alert-list mb24">${alerts.map(a=>`<div class="alert-row"><div><p>โต๊ะ ${esc(a.table_name)} · ${a.type==='bill'?'ขอเช็กบิล':'เรียกพนักงาน'}</p><small>${fmt(a.created_at)}</small></div><button class="btn secondary sm" data-action="resolve-alert" data-id="${a.id}">รับทราบ</button></div>`).join('')}</div>`:''}${metricsHtml([['ยอดชำระวันนี้',money(revenue),`${paid.length} บิลที่ชำระแล้ว`,'wallet'],['ออเดอร์วันนี้',orders.length,`${active.length} ออเดอร์อยู่ในคิว`,'receipt'],['โต๊ะที่ใช้งาน',`${occupied.length}<span style="font-size:1rem;color:var(--muted)"> / ${state.data.tables.filter(t=>t.active).length}</span>`,'มีออเดอร์ที่ยังไม่ปิดบิล','table'],['สต็อกใกล้หมด',low.length,low.length?'ควรเติมก่อนรอบถัดไป':'วัตถุดิบเพียงพอ','box']])}<div class="dashboard-grid mb24"><section class="panel"><div class="panel-title"><h2>ยอดชำระ 7 วัน</h2><span class="tiny muted">บาท</span></div>${chartHtml(sevenDays())}</section><section class="panel"><div class="panel-title"><h2>เมนูขายดีวันนี้</h2>${ico('cup')}</div>${bestHtml(bestSellers(orders))}</section></div><section class="panel"><div class="panel-title"><h2>ออเดอร์ล่าสุด</h2><button class="text-link" data-action="admin-view" data-view="orders">ดูทั้งหมด</button></div>${orderRows([...state.data.orders].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,6),true)}</section>`;}
function ticket(o){const next={new:['preparing','เริ่มเตรียม'],preparing:['ready','พร้อมเสิร์ฟ'],ready:['served','ยืนยันเสิร์ฟแล้ว']};return `<article class="ticket"><div class="ticket-top"><strong>#${esc(o.number)}</strong><span class="pill">โต๊ะ ${esc(o.table_name)}</span></div><div class="tiny muted mt16">${fmt(o.created_at)}</div><div class="ticket-items">${o.items.map(x=>`<div class="ticket-item"><span>${x.qty} × ${esc(x.name)}</span><small>${esc(itemOptions(x))}${x.note?' · '+esc(x.note):''}</small></div>`).join('')}</div>${o.note?`<p class="ticket-note">${esc(o.note)}</p>`:''}<div class="ticket-total"><span>${o.items.reduce((a,x)=>a+x.qty,0)} รายการ</span><strong>${money(o.total)}</strong></div>${next[o.status]?`<button class="btn" data-action="order-status" data-id="${esc(o.id)}" data-status="${next[o.status][0]}">${next[o.status][1]}</button>`:''}${o.status==='new'?`<button class="text-link mt16" data-action="cancel-confirm" data-id="${esc(o.id)}">ยกเลิกออเดอร์</button>`:''}</article>`;}
function ordersHtml(){const filtered=state.data.orders.filter(o=>!state.orderSearch||(String(o.number)+' '+o.table_name+' '+o.items.map(x=>x.name).join(' ')).includes(state.orderSearch));return `${heading('ออเดอร์','รับออเดอร์ เตรียม และเสิร์ฟตามลำดับ')}<div class="board-filters"><div class="categories"><button class="chip ${state.orderFilter==='live'?'active':''}" data-action="order-filter" data-filter="live">คิวปัจจุบัน</button><button class="chip ${state.orderFilter==='served'?'active':''}" data-action="order-filter" data-filter="served">เสิร์ฟแล้ว / รอชำระ</button><button class="chip ${state.orderFilter==='all'?'active':''}" data-action="order-filter" data-filter="all">ประวัติทั้งหมด</button></div><div class="searchbox">${ico('search')}<input id="order-search" type="search" placeholder="เลขออเดอร์ / โต๊ะ" value="${esc(state.orderSearch)}" aria-label="ค้นหาออเดอร์"></div></div>${state.orderFilter==='live'?`<div class="order-board">${['new','preparing','ready'].map(s=>{const items=filtered.filter(o=>o.status===s&&!o.paid);return `<section class="board-column"><div class="column-title"><span>${labels[s]}</span><span>${items.length}</span></div><div class="tickets">${items.map(ticket).join('')}</div>${!items.length?'<div class="empty small">ยังไม่มีออเดอร์ในคิวนี้</div>':''}</section>`;}).join('')}</div>`:`<section class="panel">${orderRows(filtered.filter(o=>state.orderFilter==='all'||o.status==='served'&&!o.paid).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),true)}</section>`}`;}
function tablesHtml(){return `${heading('โต๊ะและบิล','QR ประจำโต๊ะจะเปิดเมนูพร้อมระบุโต๊ะให้ลูกค้า',canManager()?'<button class="btn secondary" data-action="print-all-qr">'+ico('print')+'พิมพ์ QR ทุกโต๊ะ</button>':'')}<div class="tables-grid">${state.data.tables.map(t=>{const os=ordersForTable(t.id),total=os.reduce((a,x)=>a+x.total,0),unready=os.some(o=>o.status!=='served');return `<section class="table-card ${os.length?'occupied':''}"><div class="table-card-head"><span class="pill ${!t.active?'red':os.length?'gold':'green'}">${!t.active?'ปิดใช้งาน':os.length?'มีลูกค้า':'ว่าง'}</span>${canManager()?`<button class="icon-btn" style="width:30px;height:30px;border:0" data-action="edit-table" data-id="${t.id}" aria-label="แก้ไขโต๊ะ ${esc(t.name)}">${ico('edit')}</button>`:ico('table')}</div><div class="table-number"><small>โต๊ะ</small>${esc(t.name)}</div><div class="table-status">${t.seats} ที่นั่ง · ${os.length?os.length+' ออเดอร์':'ยังไม่มีออเดอร์'}</div><div class="table-amount">${money(total)}</div><div class="stack" style="gap:9px"><button class="btn ${os.length?'':'secondary'}" data-action="table-bill" data-id="${t.id}" ${!os.length?'disabled':''}>${unready?'ดูบิล / ออเดอร์':'เช็กบิล'}</button><button class="btn ghost sm" data-action="table-qr" data-id="${t.id}">${ico('qr')} QR โต๊ะ</button></div></section>`;}).join('')}</div>`;}
function menuAdminHtml(){return `${heading('จัดการเมนู','ราคา ตัวเลือก และการเปิดขายเมนู','<button class="btn" data-action="edit-product">'+ico('plus')+'เพิ่มเมนู</button>')}<div class="menu-admin-grid">${state.data.products.map(p=>`<article class="menu-admin-card"><div class="menu-admin-top">${photoFor(p)?`<img src="${photoFor(p)}" alt="${esc(p.name)}">`:ico(productIcon(p))}</div><div class="inner"><div class="row between mb16"><div><h3>${esc(p.name)}</h3><div class="product-en">${esc(p.en)}</div></div></div><div class="row between mb16"><span class="num" style="font-size:1.375rem">${money(p.price)}</span><span class="pill ${p.available?'green':''}">${p.available?'เปิดขาย':'ปิดขาย'}</span></div><div class="row"><button class="btn secondary sm" data-action="edit-product" data-id="${esc(p.id)}">${ico('edit')}แก้ไข</button><button class="btn ghost sm" data-action="toggle-product" data-id="${esc(p.id)}">${p.available?'ปิดขาย':'เปิดขาย'}</button></div></div></article>`).join('')}</div>`;}
function stockHtml(){const low=state.data.stock.filter(x=>x.qty<=x.low);return `${heading('สต็อกวัตถุดิบ','หักวัตถุดิบเมื่อรับออเดอร์ และคืนเมื่อยกเลิกก่อนเตรียม')} ${low.length?`<div class="info-box">${ico('box')} ${low.length} รายการถึงระดับที่ควรเติมสต็อก</div>`:''}<section class="panel mb24"><div class="table-scroll"><table class="data-table"><thead><tr><th>วัตถุดิบ</th><th>คงเหลือ</th><th>ควรเติมเมื่อเหลือ</th><th>สถานะ</th><th></th></tr></thead><tbody>${state.data.stock.map(x=>`<tr class="${x.qty<=x.low?'stock-low':''}"><td class="name-cell">${esc(x.name)}</td><td><span class="num">${Number(x.qty).toLocaleString('th-TH')}</span> <span class="tiny muted">${esc(x.unit)}</span><div class="stock-track"><span style="width:${Math.max(3,Math.min(100,x.qty/(x.low*5||1)*100))}%"></span></div></td><td class="muted">${Number(x.low).toLocaleString('th-TH')} ${esc(x.unit)}</td><td><span class="pill ${x.qty<=x.low?'gold':'green'}">${x.qty<=x.low?'ควรเติม':'เพียงพอ'}</span></td><td><button class="btn secondary sm" data-action="restock" data-id="${esc(x.id)}">${ico('plus')}เติมสต็อก</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-title"><h2>ความเคลื่อนไหวล่าสุด</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>เวลา</th><th>วัตถุดิบ</th><th>จำนวน</th><th>หมายเหตุ</th></tr></thead><tbody>${(state.data.movements||[]).slice(0,20).map(m=>`<tr><td class="tiny muted">${fmt(m.created_at)}</td><td>${esc(m.name||m.stock_name||state.data.stock.find(x=>x.id===m.stock_id)?.name||m.stock_id)}</td><td class="num">${Number(m.quantity ?? m.delta)>0?'+':''}${Number(m.quantity ?? m.delta).toLocaleString('th-TH')}</td><td class="tiny muted">${esc(m.note)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">ยังไม่มีความเคลื่อนไหว</td></tr>'}</tbody></table></div></section>`;}
function reportsHtml(){const r=state.report;return `${heading('รายงานยอดขาย','นับยอดจากบิลที่ยืนยันชำระแล้ว',`<form id="report-form" class="report-toolbar"><label class="field">ตั้งแต่<input type="date" name="from" value="${state.reportFrom}" required></label><label class="field">ถึง<input type="date" name="to" value="${state.reportTo}" required></label><button class="btn secondary" type="submit">ดูรายงาน</button><a class="btn" href="/api/admin/report.csv?from=${state.reportFrom}&to=${state.reportTo}">${ico('download')}CSV</a></form>`)}${r?`${metricsHtml([['ยอดชำระรวม',money(r.revenue),`${r.payments.length} บิล`,'wallet'],['ออเดอร์ที่ชำระ',r.order_count,'ตามวันที่ชำระบิล','receipt'],['เฉลี่ยต่อบิล',money(r.average),'ยอดชำระรวม ÷ จำนวนบิล','chart'],['ส่วนลดรวม',money(r.payments.reduce((a,x)=>a+x.discount,0)),'หักจากยอดบิลก่อนชำระ','receipt']])}<div class="report-grid"><section class="panel"><div class="panel-title"><h2>ยอดชำระรายวัน</h2><span class="tiny muted">บาท</span></div>${chartHtml(r.daily.slice(-14))}${r.daily.length>14?'<p class="tiny muted mt16">กราฟแสดง 14 วันล่าสุดในช่วงที่เลือก</p>':''}</section><section class="panel"><div class="panel-title"><h2>เมนูขายดี</h2></div>${bestHtml(r.best_sellers)}</section></div><section class="panel"><div class="panel-title"><h2>บิลที่ชำระแล้ว</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>บิล</th><th>โต๊ะ</th><th>เวลา</th><th>ช่องทาง</th><th>ยอดชำระ</th><th></th></tr></thead><tbody>${r.payments.map(p=>`<tr><td class="num">#${esc(String(p.id).slice(0,8))}</td><td>${esc(p.table_name||state.data.tables.find(t=>String(t.id)===String(p.table_id))?.name||p.table_id)}</td><td class="tiny muted">${fmt(p.created_at)}</td><td>${{cash:'เงินสด',transfer:'โอนเงิน',card:'บัตร'}[p.method]||esc(p.method)}</td><td class="num">${money(p.amount)}</td><td><button class="btn secondary sm" data-action="receipt" data-id="${esc(p.id)}">ใบเสร็จ</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีบิลในช่วงนี้</td></tr>'}</tbody></table></div></section>`:'<div class="empty">กำลังอ่านรายงาน…</div>'}`;}
function staffHtml(){return `${heading('พนักงาน','กำหนดสิทธิ์ตามหน้าที่ของแต่ละคน','<button class="btn" data-action="edit-staff">'+ico('plus')+'เพิ่มพนักงาน</button>')}<section class="panel mb24"><div class="table-scroll"><table class="data-table"><thead><tr><th>ชื่อ</th><th>ชื่อเข้าสู่ระบบ</th><th>สิทธิ์</th><th>สถานะ</th><th></th></tr></thead><tbody>${state.data.staff.map(u=>`<tr><td class="name-cell">${esc(u.name)}</td><td class="muted">${esc(u.username)}</td><td>${roles[u.role]}</td><td><span class="pill ${u.active?'green':''}">${u.active?'ใช้งาน':'ปิดใช้งาน'}</span></td><td><button class="btn secondary sm" data-action="edit-staff" data-id="${u.id}">แก้ไข</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2 class="mb16">สิทธิ์การใช้งาน</h2><div class="role-card"><h3>ผู้จัดการ</h3><p>จัดการร้าน เมนู สต็อก พนักงาน ออเดอร์ และยอดขาย</p></div><div class="role-card"><h3>แคชเชียร์</h3><p>จัดการออเดอร์ ดูโต๊ะ รับชำระ และดูรายงาน</p></div><div class="role-card"><h3>บาริสต้า</h3><p>รับออเดอร์ อัปเดตการเตรียม และดูข้อมูลโต๊ะ</p></div></section>`;}
function settingsHtml(){const s=state.data.shop;return `${heading('ตั้งค่าร้าน','ข้อมูลร้านและการรับออเดอร์')}<div class="settings-grid"><section class="panel"><form id="settings-form" class="stack gap24"><div class="form-grid"><label class="field full">ชื่อร้าน<input name="name" value="${esc(s.name)}" required maxlength="60"></label><label class="field full">คำอธิบายร้าน<input name="subtitle" value="${esc(s.subtitle)}" maxlength="140"></label><label class="field full">เวลาเปิดร้าน<input name="opening_hours" value="${esc(s.opening_hours)}" maxlength="60" required></label><label class="field full">ที่อยู่เว็บสำหรับ QR<input name="public_url" type="url" value="${esc(s.public_url||'')}" placeholder="เช่น http://192.168.1.10:8787"><span class="tiny">ใช้ที่อยู่ที่มือถือใน Wi-Fi เดียวกันเปิดได้ ก่อนพิมพ์ QR</span></label></div><label class="check"><input type="checkbox" name="open" ${s.open?'checked':''}>เปิดรับออเดอร์</label><label class="check"><input type="checkbox" name="demo" ${s.demo?'checked':''}>แสดงโหมดร้านตัวอย่าง และปุ่มเลือกโต๊ะทดลอง</label><div><button class="btn" type="submit">บันทึกข้อมูลร้าน</button></div></form></section><section class="panel"><h2 class="mb16">การรับชำระ</h2><p class="small muted">ลูกค้าสั่งจากโต๊ะ และชำระที่เคาน์เตอร์ พนักงานตรวจสอบยอดก่อนยืนยันเงินสด โอนเงิน หรือบัตร</p><div class="line"></div><p class="small muted">การเลือกช่องทางในระบบเป็นการบันทึกการรับชำระ ต้องตรวจสอบกับเงินสดหรือรายการจากธนาคารก่อนยืนยัน</p><div class="line"></div><h3 class="mb16">ข้อมูลร้าน</h3><p class="small muted">ออเดอร์ บิล และสต็อกบันทึกในฐานข้อมูลของร้าน และคงอยู่หลังปิดแล้วเปิดระบบใหม่</p><p class="tiny muted mt16">รายงานใช้เวลาประเทศไทย · ราคาสุทธิ ไม่มีการคิดภาษีหรือค่าบริการเพิ่มในตัวอย่างนี้</p></section></div>`;}
function renderAdmin(){if(!state.data||!state.user)return;const pages=visiblePages();if(!pages.some(([p])=>p===state.view))state.view='overview';const title=adminPages.find(([p])=>p===state.view)?.[2];const main={overview:overviewHtml,orders:ordersHtml,tables:tablesHtml,menu:menuAdminHtml,stock:stockHtml,reports:reportsHtml,staff:staffHtml,settings:settingsHtml}[state.view]();const newCount=state.data.orders.filter(o=>o.status==='new').length;$('#app').innerHTML=`<div class="admin-layout"><aside class="sidebar"><a class="brand" href="/">${brand()}</a><div class="sidebar-caption">จัดการร้าน</div><nav class="side-nav" aria-label="เมนูจัดการร้าน">${pages.map(([p,icon,name])=>`<button class="side-link ${state.view===p?'active':''}" data-action="admin-view" data-view="${p}">${ico(icon)}<span>${name}</span>${p==='orders'&&newCount?`<span class="count">${newCount}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><a class="sidebar-store" href="/" target="_blank">${ico('store')}เปิดหน้าร้าน</a><div class="staff-profile"><div class="row" style="gap:9px"><span class="avatar">${esc(state.user.name.charAt(0))}</span><div><div class="name">${esc(state.user.name)}</div><div class="role">${roles[state.user.role]}</div></div></div><button class="icon-btn" data-action="logout" aria-label="ออกจากระบบ">${ico('logout')}</button></div></div></aside><main class="admin-main"><header class="admin-topbar"><div class="breadcrumb">ละมุน /<span>${title}</span></div><div class="top-actions"><span class="sync">${ico('refresh')}อัปเดตทุก 5 วินาที</span>${state.data.shop.demo?'<span class="pill">ข้อมูลตัวอย่าง</span>':''}<span class="pill ${state.data.shop.open?'green':''}">${state.data.shop.open?'เปิดรับออเดอร์':'ปิดรับออเดอร์'}</span><button class="btn ghost sm mobile-admin-title" data-action="logout" aria-label="ออกจากระบบ">${ico('logout')}</button></div></header>${!state.connected?'<div class="connection-banner">การเชื่อมต่อขัดข้อง กำลังลองเชื่อมต่อใหม่</div>':''}<div class="admin-content">${main}</div></main></div>`;}
function renderLogin(error=''){clearInterval(pollTimer);$('#app').innerHTML=`<main class="login-page"><section class="login-brand"><span class="wordmark">ละมุน<span>LAMOON COFFEE</span></span><p>ดูแลร้านอย่างสบายใจ<br>ทีละแก้ว ทีละวัน</p></section><section class="login-form-side"><div class="login-form"><h1>ยินดีต้อนรับกลับ</h1><p>เข้าสู่ระบบสำหรับพนักงาน</p>${error?`<div class="error-box" role="alert">${esc(error)}</div>`:''}<form id="login-form"><label class="field">ชื่อเข้าสู่ระบบ<input name="username" autocomplete="username" required autofocus></label><label class="field">รหัสผ่าน<input name="password" type="password" autocomplete="current-password" required></label><button class="btn w-full" type="submit">เข้าสู่ระบบ</button></form><p class="tiny muted mt24">บัญชีเริ่มต้นและรหัสผ่านอยู่ในหน้าต่างที่เปิดระบบร้าน</p><div class="login-back"><a class="text-link" href="/">กลับหน้าร้าน</a></div></div></section></main>`;}
async function loadReport(){state.report=await api(`/api/admin/report?from=${state.reportFrom}&to=${state.reportTo}`);}
async function refreshAdmin(render=true){state.data=await api('/api/admin/state');if(state.view==='reports')await loadReport();if(render)renderAdmin();}
async function navigateAdmin(view){state.view=view;history.replaceState(null,'','/admin?view='+view);if(view==='reports')await loadReport();renderAdmin();}
function startPolling(){
 clearInterval(pollTimer);
 pollTimer=setInterval(async()=>{
  if(document.hidden||state.busy)return;
  try{
   if(state.admin&&state.user){
    await refreshAdmin(false);state.connected=true;
    if(!$('#modal-root').children.length&&['overview','orders','tables'].includes(state.view)&&document.activeElement?.id!=='order-search')renderAdmin();
   }else if(!state.admin&&state.menu){
    const next=await api('/api/menu'+(state.token?'?token='+encodeURIComponent(state.token):''));
    const changed=JSON.stringify([next.products,next.shop,next.table])!==JSON.stringify([state.menu.products,state.menu.shop,state.menu.table]);
    state.menu=next;
    const repriced=syncCartPrices();
    await loadOrders();const was=state.connected;state.connected=true;
    const editing=document.activeElement?.matches('input,textarea,select');
    if(!$('#modal-root').children.length&&(state.view==='history'||!was||(changed&&!editing)))renderCustomer();
    if(repriced)toast('ร้านปรับราคาเมนูแล้ว โปรดตรวจสอบยอดในรายการอีกครั้ง');
   }
  }catch{if(state.connected){state.connected=false;if(state.admin&&state.user)renderAdmin();else if(state.menu)renderCustomer();}}
 },5000);
}

function openTableBill(id){const t=state.data.tables.find(x=>String(x.id)===String(id)),orders=ordersForTable(id),total=orders.reduce((a,x)=>a+x.total,0),unfinished=orders.some(x=>x.status!=='served');showModal('บิลโต๊ะ '+esc(t.name),`${orders.map(o=>`<div class="mb16"><div class="row between mb16"><span class="num">#${esc(o.number)}</span>${statusPill(o.status)}</div>${o.items.map(x=>`<div class="history-item"><div>${x.qty} × ${esc(x.name)}<div class="tiny muted">${esc(itemOptions(x))}</div></div><span class="num">${money((x.price??x.unit_price)*x.qty)}</span></div>`).join('')}</div>`).join('')}<div class="line"></div><div class="row between mb24"><strong>ยอดก่อนส่วนลด</strong><strong class="num" style="font-size:1.5rem;font-weight:normal">${money(total)}</strong></div>${unfinished?'<div class="info-box">มีออเดอร์ที่ยังเสิร์ฟไม่ครบ ยืนยันการเสิร์ฟในหน้าคิวก่อนปิดบิล</div>':''}${canCashier()&&!unfinished?`<form id="payment-form" class="stack"><input type="hidden" name="table_id" value="${esc(id)}"><label class="field">ส่วนลด (บาท)<input name="discount" type="number" min="0" max="${total}" step="1" value="0" required></label><label class="field">ช่องทางที่รับชำระ<select name="method"><option value="cash">เงินสด</option><option value="transfer">โอนเงิน</option><option value="card">บัตร</option></select></label><p class="tiny muted">ตรวจสอบว่าได้รับเงินครบก่อนยืนยัน ระบบจะบันทึกการรับชำระและปิดบิลโต๊ะนี้</p><button class="btn" type="submit">ได้รับชำระแล้ว · ปิดบิล</button></form>`:!canCashier()?'<p class="small muted">ให้แคชเชียร์หรือผู้จัดการยืนยันรับชำระ</p>':''}`,`<button class="btn secondary" data-action="print">${ico('print')}พิมพ์บิล</button>`,true);}
function qrUrl(t){const origin=(state.data.shop.public_url||location.origin).replace(/\/$/,'');return origin+'/table/'+encodeURIComponent(t.token);}
function qrCard(t){return `<div class="qr-card"><div class="brand" style="justify-content:center">${brand()}</div><h2 class="mt24">โต๊ะ ${esc(t.name)}</h2><p class="small muted">สแกนเพื่อสั่งเมนู</p><img src="/api/admin/qr?table_id=${encodeURIComponent(t.id)}" alt="QR สำหรับโต๊ะ ${esc(t.name)}"><p class="qr-link no-print">${esc(qrUrl(t))}</p><p class="tiny muted mt16">เลขโต๊ะจะแสดงก่อนยืนยันออเดอร์</p></div>`;}
function openQr(id){const t=state.data.tables.find(x=>String(x.id)===String(id));showModal('QR ประจำโต๊ะ',qrCard(t),`<a class="btn secondary" href="${esc(qrUrl(t))}" target="_blank">ทดลองเปิดเมนู</a><button class="btn" data-action="print">${ico('print')}พิมพ์ QR</button>`);}
function recipeFields(p){const recipe=Object.entries(p.recipe||{});return `<div id="recipe-rows">${recipe.map(([id,qty])=>recipeRow(id,qty)).join('')}</div><button class="btn secondary sm" type="button" data-action="recipe-add">${ico('plus')}เพิ่มวัตถุดิบ</button>`;}
function recipeRow(id='',qty=1){return `<div class="recipe-row"><select class="recipe-stock" aria-label="วัตถุดิบ"><option value="">เลือกวัตถุดิบ</option>${state.data.stock.map(s=>`<option value="${esc(s.id)}" ${s.id===id?'selected':''}>${esc(s.name)} (${esc(s.unit)})</option>`).join('')}</select><input class="recipe-qty" type="number" min="0.01" step="0.01" value="${qty}" aria-label="จำนวนต่อเมนู"><button class="icon-btn" style="width:34px;height:42px;border-radius:9px" type="button" data-action="recipe-remove" aria-label="นำวัตถุดิบออก">${ico('close')}</button></div>`;}
function editProduct(id){const p=state.data.products.find(x=>String(x.id)===String(id))||{name:'',en:'',category:'coffee',description:'',price:85,image:'',available:true,recipe:{}};showModal(id?'แก้ไขเมนู':'เพิ่มเมนู',`<form id="product-form"><input type="hidden" name="id" value="${esc(id||'')}"><div class="form-grid"><label class="field full">ชื่อเมนู<input name="name" value="${esc(p.name)}" maxlength="80" required></label><label class="field full">ชื่อภาษาอังกฤษ<input name="en" value="${esc(p.en)}" maxlength="80"></label><label class="field">หมวด<select name="category">${Object.entries(categories).filter(([k])=>k!=='all').map(([k,n])=>`<option value="${k}" ${p.category===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">ราคา (บาท)<input name="price" type="number" min="1" max="10000" step="1" value="${p.price}" required></label><label class="field full">คำอธิบาย<textarea name="description" maxlength="200">${esc(p.description)}</textarea></label><label class="field full">ภาพเมนู<select name="image"><option value="">ใช้สัญลักษณ์หมวด</option>${[['latte','ลาเต้'],['matcha','มัทฉะลาเต้'],['croissant','ครัวซองต์']].map(([k,l])=>`<option value="${k}" ${p.image===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="check full"><input name="available" type="checkbox" ${p.available?'checked':''}>เปิดขายเมนูนี้</label><div class="full"><h3 class="mb16">วัตถุดิบต่อ 1 รายการ</h3><p class="tiny muted mb16">ใช้จำนวนตามหน่วยสต็อก แก้วใหญ่ใช้เพิ่ม 25% นมโอ๊ตแทนที่นมปกติ</p>${recipeFields(p)}</div><div class="full mt16"><button class="btn w-full" type="submit">บันทึกเมนู</button></div></div></form>`, '',true);}
function editTable(id){const t=state.data.tables.find(x=>String(x.id)===String(id));showModal('แก้ไขโต๊ะ '+esc(t.name),`<form id="table-form" class="stack"><input name="id" type="hidden" value="${t.id}"><label class="field">ชื่อ / เลขโต๊ะ<input name="name" value="${esc(t.name)}" required maxlength="20"></label><label class="field">จำนวนที่นั่ง<input name="seats" type="number" value="${t.seats}" min="1" max="20" required></label><label class="check"><input name="active" type="checkbox" ${t.active?'checked':''}>เปิดใช้งานโต๊ะนี้</label><label class="check"><input name="rotate" type="checkbox">ออก QR ใหม่ และยกเลิก QR เดิม</label><p class="tiny muted">หลังออก QR ใหม่ ต้องเปลี่ยนป้ายบนโต๊ะ จะเปลี่ยนได้เมื่อโต๊ะไม่มีบิลค้าง</p><button class="btn" type="submit">บันทึกโต๊ะ</button></form>`);}
function editStaff(id){const u=state.data.staff.find(x=>String(x.id)===String(id))||{username:'',name:'',role:'barista',active:true};showModal(id?'แก้ไขพนักงาน':'เพิ่มพนักงาน',`<form id="staff-form" class="stack"><input type="hidden" name="id" value="${esc(id||'')}"><label class="field">ชื่อพนักงาน<input name="name" value="${esc(u.name)}" maxlength="60" required></label><label class="field">ชื่อเข้าสู่ระบบ<input name="username" value="${esc(u.username)}" maxlength="40" minlength="3" pattern="[A-Za-z0-9_.-]+" required><span class="tiny">ใช้ตัวอักษรอังกฤษ ตัวเลข จุด ขีด หรือขีดล่าง</span></label><label class="field">สิทธิ์<select name="role">${Object.entries(roles).map(([k,l])=>`<option value="${k}" ${k===u.role?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">${id?'รหัสผ่านใหม่ (เว้นว่างเพื่อใช้เดิม)':'รหัสผ่าน'}<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" ${!id?'required':''}><span class="tiny">อย่างน้อย 10 ตัวอักษร</span></label><label class="check"><input name="active" type="checkbox" ${u.active?'checked':''}>เปิดใช้งานบัญชี</label><button class="btn" type="submit">บันทึกพนักงาน</button></form>`);}
async function showReceipt(id){const r=await api('/api/admin/receipt?id='+encodeURIComponent(id)),p=r.payment;showModal('ใบเสร็จรับเงิน',`<div class="receipt"><div class="brand">${ico("cup")}<span class="wordmark">${esc(r.shop.name)}<span>LAMOON COFFEE</span></span></div><h3>ใบเสร็จรับเงิน</h3><p>บิล #${esc(String(p.id).slice(0,8))} · ${fmt(p.created_at)}</p><p>โต๊ะ ${esc(p.table_name || p.table_id)}</p><div class="receipt-items">${r.orders.flatMap(o=>o.items).map(x=>`<div class="row between"><span>${x.qty} × ${esc(x.name)}</span><span class="num">${money((x.price??x.unit_price)*x.qty)}</span></div>`).join('')}</div><div class="row between"><span>ยอดก่อนส่วนลด</span><span class="num">${money(p.amount+p.discount)}</span></div><div class="row between"><span>ส่วนลด</span><span class="num">${money(p.discount)}</span></div><div class="row between mt16"><strong>ยอดชำระ</strong><strong class="num" style="font-size:1.5rem">${money(p.amount)}</strong></div><p class="mt16">รับชำระด้วย${{cash:'เงินสด',transfer:'โอนเงิน',card:'บัตร'}[p.method]}</p><p class="mt24">ขอบคุณที่มาพักสักนิดกับเรา</p><p class="tiny muted mt16">ใบรับเงินของร้าน · ไม่ใช่ใบกำกับภาษี</p></div>`,`<button class="btn" data-action="print">${ico('print')}พิมพ์ใบเสร็จ</button>`);}
async function act(action,el){if(state.busy&&['customize','add-cart','cart-qty','cart-remove','custom-qty','option'].includes(action))return;switch(action){
 case 'close-modal':closeModal();break;
 case 'backdrop':break;
 case 'customer-view':state.view=el.dataset.view;renderCustomer();break;
 case 'category':state.category=el.dataset.category;renderCustomer();break;
 case 'customize':{const p=state.menu.products.find(x=>String(x.id)===el.dataset.id);if(!p.available){toast('เมนูนี้หมดชั่วคราว',true);break;}state.custom={id:p.id,options:{temperature:'iced',size:'regular',sweetness:'50',milk:'regular',shot:false},qty:1,note:''};renderCustomize();break;}
 case 'option':captureCustom();state.custom.options[el.dataset.field]=el.dataset.value;renderCustomize();break;
 case 'custom-qty':captureCustom();state.custom.qty=Math.max(1,Math.min(20,state.custom.qty+Number(el.dataset.delta)));renderCustomize();break;
 case 'add-cart':{captureCustom();const c=state.custom,p=state.menu.products.find(x=>x.id===c.id);if(!state.menu.table){toast('กรุณาสแกน QR ที่โต๊ะก่อนสั่ง',true);break;}const key=JSON.stringify([p.id,c.options,c.note]),found=state.cart.find(x=>x.key===key);if(found)found.qty=Math.min(20,found.qty+c.qty);else state.cart.push({key,product_id:p.id,name:p.name,options:{...c.options},qty:c.qty,note:c.note,price:calcPrice(p,c.options)});changedCart();closeModal();renderCustomer();toast('เพิ่ม '+p.name+' แล้ว');break;}
 case 'cart-qty':{const i=Number(el.dataset.index);state.cart[i].qty+=Number(el.dataset.delta);if(state.cart[i].qty<1)state.cart.splice(i,1);else state.cart[i].qty=Math.min(20,state.cart[i].qty);changedCart();if($('#modal-root').children.length){closeModal();showCart();}else renderCustomer();break;}
 case 'cart-remove':state.cart.splice(Number(el.dataset.index),1);changedCart();if($('#modal-root').children.length){closeModal();showCart();}else renderCustomer();break;
 case 'show-cart':showCart();break;
 case 'submit-order':await submitOrder();break;
 case 'service':{if(!state.menu.table)return;await api('/api/service',{token:state.token,type:el.dataset.type});toast(el.dataset.type==='bill'?'แจ้งพนักงานให้มาเช็กบิลแล้ว':'แจ้งพนักงานแล้ว กรุณารอสักครู่');break;}
 case 'admin-view':await navigateAdmin(el.dataset.view);break;
 case 'logout':await api('/api/logout',{});state.user=null;renderLogin();break;
 case 'order-filter':state.orderFilter=el.dataset.filter;renderAdmin();break;
 case 'order-status':await api('/api/admin/order',{id:Number(el.dataset.id),status:el.dataset.status});await refreshAdmin();toast('อัปเดตสถานะแล้ว');break;
 case 'cancel-confirm':showModal('ยกเลิกออเดอร์นี้',`<p class="small muted">จะคืนวัตถุดิบที่จองไว้ และนำออเดอร์ออกจากคิว ยกเลิกได้เฉพาะก่อนเริ่มเตรียม</p>`,`<button class="btn secondary" data-action="close-modal">กลับ</button><button class="btn danger" data-action="cancel-order" data-id="${esc(el.dataset.id)}">ยืนยันยกเลิก</button>`);break;
 case 'cancel-order':await api('/api/admin/order',{id:Number(el.dataset.id),status:'cancelled'});closeModal();await refreshAdmin();toast('ยกเลิกและคืนสต็อกแล้ว');break;
 case 'order-detail':{const o=state.data.orders.find(x=>String(x.id)===el.dataset.id||String(x.id)===el.dataset.id);showModal('ออเดอร์ #'+esc(o.number),`<div class="row between mb16"><span class="pill">โต๊ะ ${esc(o.table_name)}</span>${o.paid?'<span class="pill green">ชำระแล้ว</span>':statusPill(o.status)}</div><p class="tiny muted mb16">${fmt(o.created_at)}</p>${o.items.map(x=>`<div class="history-item"><div>${x.qty} × ${esc(x.name)}<div class="tiny muted">${esc(itemOptions(x))}</div>${x.note?`<div class="tiny">${esc(x.note)}</div>`:''}</div><span class="num">${money((x.price??x.unit_price)*x.qty)}</span></div>`).join('')}${o.note?`<p class="ticket-note">${esc(o.note)}</p>`:''}<div class="line"></div><div class="row between"><strong>รวม</strong><span class="num" style="font-size:1.5rem">${money(o.total)}</span></div>`);break;}
 case 'resolve-alert':await api('/api/admin/alert',{id:Number(el.dataset.id)});await refreshAdmin();toast('รับทราบแล้ว');break;
 case 'table-bill':openTableBill(el.dataset.id);break;
 case 'table-qr':openQr(el.dataset.id);break;
 case 'edit-table':editTable(el.dataset.id);break;
 case 'print-all-qr':showModal('QR ทุกโต๊ะ',state.data.tables.filter(t=>t.active).map(qrCard).join('<div class="line"></div>'),`<button class="btn" data-action="print">${ico('print')}พิมพ์ทั้งหมด</button>`,true);break;
 case 'edit-product':editProduct(el.dataset.id);break;
 case 'toggle-product':{const p=state.data.products.find(x=>String(x.id)===el.dataset.id);await api('/api/admin/product',{...p,available:!p.available});await refreshAdmin();toast('บันทึกการเปิดขายแล้ว');break;}
 case 'recipe-add':$('#recipe-rows').insertAdjacentHTML('beforeend',recipeRow());break;
 case 'recipe-remove':el.closest('.recipe-row').remove();break;
 case 'restock':{const s=state.data.stock.find(x=>String(x.id)===el.dataset.id);showModal('เติม '+esc(s.name),`<form id="stock-form" class="stack"><input name="id" type="hidden" value="${esc(s.id)}"><p class="small muted">คงเหลือ ${Number(s.qty).toLocaleString('th-TH')} ${esc(s.unit)}</p><label class="field">จำนวนที่เติม (${esc(s.unit)})<input name="quantity" type="number" min="0.01" step="0.01" max="1000000" required></label><label class="field">หมายเหตุ<input name="note" maxlength="160" placeholder="เช่น รับจากซัพพลายเออร์"></label><button class="btn" type="submit">บันทึกการเติมสต็อก</button></form>`);break;}
 case 'edit-staff':editStaff(el.dataset.id);break;
 case 'receipt':await showReceipt(el.dataset.id);break;
 case 'print':window.print();break;
 }}
function showCart(){showModal('รายการที่เลือก',cartHtml(true),' ',false,'cart-modal');$('.cart-modal .modal-body').style.padding='0';}
async function submitOrder(){
 if(state.busy||!state.cart.length||!state.menu.table)return;
 state.cartNote=$('#cart-note-modal')?.value??$('#cart-note')?.value??state.cartNote??'';
 state.busy=true;
 document.querySelectorAll('.cart-note').forEach(x=>x.disabled=true);
 document.querySelectorAll('[data-action="submit-order"]').forEach(x=>{x.disabled=true;x.textContent='กำลังส่งออเดอร์…';});
 try{
  state.menu=await api('/api/menu?token='+encodeURIComponent(state.token));
  if(syncCartPrices()){
   const wasModal=Boolean($('.cart-modal'));state.busy=false;
   if(wasModal){closeModal();showCart();}else renderCustomer();
   toast('ราคาเมนูเปลี่ยนแล้ว กรุณาตรวจสอบยอดและยืนยันอีกครั้ง',true);return;
  }
  const r=await api('/api/orders',{token:state.token,request_id:state.requestId,items:state.cart.map(({product_id,qty,options,note})=>({product_id,qty,options,note})),note:state.cartNote});
  const refs=storedOrders();
  if(!refs.some(x=>x.id===r.order.id))refs.push({id:r.order.id,key:r.order.receipt_key});
  try{localStorage.setItem(storageKey('orders'),JSON.stringify(refs));}catch{}
  state.orders=[r.order,...state.orders.filter(o=>o.id!==r.order.id)];
  state.cart=[];state.cartNote='';changedCart();state.busy=false;closeModal();renderCustomer();
  showModal('ร้านได้รับออเดอร์แล้ว',`<div class="success-content"><div class="success-icon">${ico('check','large')}</div><h2>กำลังเตรียมความอร่อย</h2><p>ออเดอร์สำหรับโต๊ะ ${esc(r.order.table_name)}</p><strong>#${esc(r.order.number)}</strong><p>เราจะนำไปเสิร์ฟที่โต๊ะของคุณ</p><p class="small mt16">ยอดรวม ${money(r.order.total)}</p></div>`,`<button class="btn w-full" data-action="close-and-history">ติดตามออเดอร์</button>`);
 }catch(e){
  toast(e.message,true);
  document.querySelectorAll('[data-action="submit-order"]').forEach(x=>{x.disabled=false;x.textContent='ลองยืนยันออเดอร์อีกครั้ง';});
 }finally{
  state.busy=false;document.querySelectorAll('.cart-note').forEach(x=>x.disabled=false);
 }
}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(action==='backdrop'){if(e.target===el)closeModal();return;}if(action==='close-and-history'){closeModal();state.view='history';renderCustomer();return;}try{await act(action,el);}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').children.length){closeModal();return;}if(e.key==='Tab'&&$('#modal-root').children.length){const focusable=[...document.querySelectorAll('.modal button:not(:disabled),.modal a,.modal input,.modal select,.modal textarea')].filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[role="button"]')){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){state.search=e.target.value;$('#menu-cards').innerHTML=menuCardsHtml();}if(e.target.id==='order-search'){state.orderSearch=e.target.value;const pos=e.target.selectionStart;renderAdmin();const input=$('#order-search');input.focus();input.setSelectionRange(pos,pos);}if(e.target.id==='item-note'&&state.custom)state.custom.note=e.target.value;if(e.target.id==='cart-note'||e.target.id==='cart-note-modal'){state.cartNote=e.target.value;changedCart();}});
document.addEventListener('change',e=>{if(e.target.id==='demo-table')location.href='/table/'+encodeURIComponent(e.target.value);if(e.target.id==='extra-shot'&&state.custom){captureCustom();const p=state.menu.products.find(x=>x.id===state.custom.id);$('#custom-total').textContent=money(calcPrice(p,state.custom.options)*state.custom.qty);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const f=new FormData(form),data=Object.fromEntries(f),btn=form.querySelector('button[type="submit"]');if(btn?.disabled)return;if(btn)btn.disabled=true;try{switch(form.id){
 case 'login-form':{const r=await api('/api/login',data);state.user=r.user;state.csrf=r.csrf;await refreshAdmin();startPolling();break;}
 case 'payment-form':{const r=await api('/api/admin/payment',{table_id:Number(data.table_id),method:data.method,discount:Number(data.discount)});closeModal();await refreshAdmin();toast('ปิดบิลและบันทึกการรับชำระแล้ว');await showReceipt(r.payment.id);break;}
 case 'product-form':{const recipe={};form.querySelectorAll('.recipe-row').forEach(row=>{const id=row.querySelector('select').value,qty=Number(row.querySelector('input').value);if(id&&qty>0)recipe[id]=(recipe[id]||0)+qty;});await api('/api/admin/product',{...data,id:data.id?Number(data.id):undefined,price:Number(data.price),available:f.has('available'),recipe});closeModal();await refreshAdmin();toast('บันทึกเมนูแล้ว');break;}
 case 'stock-form':await api('/api/admin/stock',{...data,quantity:Number(data.quantity)});closeModal();await refreshAdmin();toast('เติมสต็อกแล้ว');break;
 case 'table-form':await api('/api/admin/table',{...data,id:Number(data.id),seats:Number(data.seats),active:f.has('active'),rotate:f.has('rotate')});closeModal();await refreshAdmin();toast('บันทึกโต๊ะแล้ว');break;
 case 'staff-form':await api('/api/admin/staff',{...data,id:data.id?Number(data.id):undefined,active:f.has('active')});closeModal();if(Number(data.id)===state.user.id&&data.password){state.user=null;state.csrf='';renderLogin();toast('บันทึกแล้ว กรุณาเข้าสู่ระบบด้วยรหัสผ่านใหม่');}else{await refreshAdmin();toast('บันทึกพนักงานแล้ว');}break;
 case 'settings-form':await api('/api/admin/settings',{...data,open:f.has('open'),demo:f.has('demo')});await refreshAdmin();toast('บันทึกข้อมูลร้านแล้ว');break;
 case 'report-form':if(data.from>data.to)throw Error('วันที่เริ่มต้องไม่อยู่หลังวันที่สิ้นสุด');state.reportFrom=data.from;state.reportTo=data.to;await loadReport();renderAdmin();break;
 }}catch(err){if(form.id==='login-form')renderLogin(err.message);else toast(err.message,true);}finally{if(btn)btn.disabled=false;}});
async function init(){try{if(state.admin){const session=await api('/api/session');state.user=session.user;state.csrf=session.csrf;if(!state.user){renderLogin();return;}await refreshAdmin();}else await loadCustomer();startPolling();}catch(e){$('#app').innerHTML=`<div class="initial"><span class="wordmark">ละมุน<span>LAMOON COFFEE</span></span><div class="error-box">${esc(e.message)}</div><p class="small">ตรวจสอบว่าร้านเปิดระบบอยู่ และ QR ยังใช้งานได้</p><button class="btn secondary" onclick="location.reload()">ลองอีกครั้ง</button></div>`;}}
init();
